        >
          <u className="underline-offset-2">{item[0]}</u>
          {item.slice(1)}
        </button>
      ))}
    </nav>
  )
}

'use client'

import { useId, useRef, useState } from 'react'
import type { KeyboardEvent, ReactNode } from 'react'
import { cn } from '@/lib/utils'

export type RetroTab = { id: string; label: string; content: ReactNode }

type RetroTabsProps = {
  tabs: RetroTab[]
  value?: string
  onValueChange?: (id: string) => void
  className?: string
  panelClassName?: string
}

export function RetroTabs({ tabs, value, onValueChange, className, panelClassName }: RetroTabsProps) {
  const baseId = useId()
  const [inner, setInner] = useState(tabs[0]?.id)
  const active = value ?? inner
  const buttons = useRef<Record<string, HTMLButtonElement | null>>({})

  function setActive(id: string) {
    setInner(id)
    onValueChange?.(id)
  }

  function onKeyDown(event: KeyboardEvent, index: number) {
    const step = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0
    if (!step) return
    event.preventDefault()
    const next = tabs[(index + step + tabs.length) % tabs.length]
    setActive(next.id)
    buttons.current[next.id]?.focus()
  }

  return (
    <div className={cn('flex flex-col', className)}>
      <div role="tablist" className="flex items-end gap-0.5 px-1">
        {tabs.map((tab, index) => {
          const selected = tab.id === active
          return (
            <button
              key={tab.id}
              ref={(node) => {
                buttons.current[tab.id] = node
              }}
              id={`${baseId}-tab-${tab.id}`}
              role="tab"
              type="button"
              aria-selected={selected}
              aria-controls={`${baseId}-panel-${tab.id}`}
              tabIndex={selected ? 0 : -1}
              onClick={() => setActive(tab.id)}
              onKeyDown={(event) => onKeyDown(event, index)}
              className={cn(
                'rt-raised relative rounded-b-none px-3.5 text-[13px] font-medium transition-[filter] hover:brightness-105',
                'focus-visible:outline-2 focus-visible:-outline-offset-4 focus-visible:outline-rt-accent',
                selected ? 'z-10 -mb-px h-7.5 border-b-rt-face bg-rt-face' : 'h-6.5 text-rt-ink/75',
              )}
            >
              {tab.label}
            </button>
          )
        })}
      </div>
      {tabs.map((tab) => (
        <div
          key={tab.id}
          id={`${baseId}-panel-${tab.id}`}
          role="tabpanel"
          aria-labelledby={`${baseId}-tab-${tab.id}`}
          hidden={tab.id !== active}
          className={panelClassName ?? 'rt-raised rounded-[3px] p-3'}
        >
          {tab.content}
        </div>
      ))}
    </div>
  )
}

import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

export const RETRO_THEMES = [
  { id: 'navy', name: 'Classic Navy', tone: 'light', swatch: ['#dde0e6', '#2b49c9', '#167a84'] },
  { id: 'hotdog', name: 'Hot Dog Stand', tone: 'light', swatch: ['#ffe14d', '#e01b1b', '#c41515'] },
  { id: 'phosphor', name: 'Phosphor Green', tone: 'dark', swatch: ['#0b1f10', '#33ff77', '#020a04'] },
  { id: 'amber', name: 'Amber Terminal', tone: 'dark', swatch: ['#1c1203', '#ffb000', '#0a0600'] },
  { id: 'rose', name: 'Rose / Pastel', tone: 'light', swatch: ['#f6dfe8', '#d9498a', '#8fcbc0'] },
  { id: 'dark', name: 'Dark Mode', tone: 'dark', swatch: ['#2b2f3a', '#5b7cff', '#0f1a24'] },
] as const

export const RETRO_FONTS = [
  { id: 'plex', name: 'IBM Plex' },
  { id: 'pixel', name: 'Pixel (VT323 + Press Start 2P)' },
  { id: 'system', name: 'System (Chicago-like)' },
  { id: 'mono', name: 'Mono' },
] as const

export type RetroThemeId = (typeof RETRO_THEMES)[number]['id']
export type RetroFontId = (typeof RETRO_FONTS)[number]['id']

type RetroThemeProps = HTMLAttributes<HTMLDivElement> & {
  theme?: RetroThemeId
  font?: RetroFontId
}

export function RetroTheme({ theme = 'navy', font = 'plex', className, children, ...props }: RetroThemeProps) {
  const tone = RETRO_THEMES.find((entry) => entry.id === theme)?.tone ?? 'light'
  return (
    <div
      data-rt-theme={theme}
      data-rt-font={font}
      data-rt-tone={tone}
      className={cn('font-rt', className)}
      {...props}
    >
      {children}
    </div>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

type RetroWindowProps = {
  title: string
  children: ReactNode
  menu?: ReactNode
  status?: ReactNode
  onClose?: () => void
  className?: string
  bodyClassName?: string
  titleAs?: 'h2' | 'h3' | 'p'
}

function TitleGlyph({ kind }: { kind: 'min' | 'max' }) {
  return (
    <svg viewBox="0 0 8 8" className="size-2 fill-current" aria-hidden="true">
      {kind === 'min' ? <path d="M0 2h8L4 7z" /> : <path d="M0 6h8L4 1z" />}
    </svg>
  )
}

export function RetroWindow({
  title,
  children,
  menu,
  status,
  onClose,
  className,
  bodyClassName,
  titleAs: Title = 'h2',
}: RetroWindowProps) {
  const boxClass =
    'rt-raised flex size-5.5 shrink-0 items-center justify-center text-rt-ink'

  return (
    <section
      aria-label={title}
      className={cn(
        'flex flex-col rounded-[5px] border border-rt-line bg-rt-face p-0.75 font-rt text-[13px] text-rt-ink',
        'shadow-[inset_1px_1px_0_var(--color-rt-light),0_2px_0_rgb(0_0_0/0.25),0_16px_32px_-12px_rgb(0_0_0/0.55)]',
        className,
      )}
    >
      <header className="flex items-stretch gap-0.75">
        {onClose ? (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close window"
            className={cn(
              boxClass,
              'transition-colors hover:bg-rt-light active:rt-pressed focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rt-accent',
            )}
          >
            <span className="block h-0.75 w-3 rounded-[1px] border border-rt-line bg-rt-paper" />
          </button>
        ) : (
          <span aria-hidden="true" className={boxClass}>
            <span className="block h-0.75 w-3 rounded-[1px] border border-rt-line bg-rt-paper" />
          </span>
        )}
        <Title className="rt-title flex h-5.5 min-w-0 flex-1 items-center truncate rounded-[2px] px-2.5 font-rt-mono text-[11px] font-semibold tracking-widest uppercase">
          {title}
        </Title>
        <span aria-hidden="true" className={boxClass}>
          <TitleGlyph kind="min" />
        </span>
        <span aria-hidden="true" className={boxClass}>
          <TitleGlyph kind="max" />
        </span>
      </header>

      {menu ? <div className="mt-0.75">{menu}</div> : null}

      <div className={cn('mt-0.75 flex-1 border-t border-rt-shadow/60', bodyClassName)}>{children}</div>

      {status ? (
        <footer className="rt-sunken mt-0.75 flex items-center gap-2 px-2 py-0.5 text-[12px]">
          {status}
        </footer>
      ) : null}
    </section>
  )
}
